# Shopping Cart Price Calculator

Below is a production-quality implementation using `Decimal` for money, guarding against negative totals, and preventing duplicate discount codes per cart.

```python
from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal, ROUND_HALF_UP
from typing import Optional


# ---------------------------------------------------------------------------
# Money helpers
# ---------------------------------------------------------------------------
CENTS = Decimal("0.01")


def _q(amount: Decimal) -> Decimal:
    """Quantize to cents, round half-up (standard retail rounding)."""
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


# ---------------------------------------------------------------------------
# Domain objects
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal  # must be >= 0


@dataclass
class LineItem:
    product: Product
    quantity: int

    def __post_init__(self) -> None:
        if self.quantity <= 0:
            raise ValueError(f"Quantity for {self.product.sku} must be > 0")
        if self.product.price < 0:
            raise ValueError(f"Price for {self.product.sku} must be >= 0")

    @property
    def subtotal(self) -> Decimal:
        return _q(self.product.price * self.quantity)


# ---------------------------------------------------------------------------
# Discounts
# ---------------------------------------------------------------------------
class Discount:
    """Base class for a discount strategy."""
    code: str

    def apply(self, subtotal: Decimal) -> Decimal:
        """Return the amount to subtract (>= 0). Never returns a negative."""
        raise NotImplementedError


@dataclass(frozen=True)
class PercentageDiscount(Discount):
    code: str
    percent: Decimal  # e.g. Decimal("10") for 10%

    def __post_init__(self) -> None:
        if not (Decimal("0") <= self.percent <= Decimal("100")):
            raise ValueError(f"Invalid percent: {self.percent}")

    def apply(self, subtotal: Decimal) -> Decimal:
        discount = subtotal * self.percent / Decimal("100")
        return _q(max(Decimal("0"), discount))


@dataclass(frozen=True)
class FixedAmountDiscount(Discount):
    code: str
    amount: Decimal

    def __post_init__(self) -> None:
        if self.amount < 0:
            raise ValueError("Discount amount must be >= 0")

    def apply(self, subtotal: Decimal) -> Decimal:
        # Cannot exceed the subtotal (no negative final price).
        return _q(min(self.amount, subtotal))


# ---------------------------------------------------------------------------
# Cart
# ---------------------------------------------------------------------------
class DiscountAlreadyApplied(Exception):
    pass


@dataclass
class ShoppingCart:
    items: list[LineItem] = field(default_factory=list)
    # Tracks applied codes so the same code is never applied twice.
    _applied_codes: set[str] = field(default_factory=set)
    _applied_discounts: list[Discount] = field(default_factory=list)

    # -- Mutation -----------------------------------------------------------
    def add_item(self, product: Product, quantity: int = 1) -> None:
        # Merge with existing line for the same SKU for tidiness.
        for line in self.items:
            if line.product.sku == product.sku:
                line.quantity += quantity
                return
        self.items.append(LineItem(product, quantity))

    def apply_discount(self, discount: Discount) -> None:
        code = discount.code.strip().upper()
        if not code:
            raise ValueError("Discount code must not be empty")
        if code in self._applied_codes:
            raise DiscountAlreadyApplied(
                f"Discount code '{code}' has already been applied to this cart"
            )
        self._applied_codes.add(code)
        self._applied_discounts.append(discount)

    # -- Totals -------------------------------------------------------------
    @property
    def subtotal(self) -> Decimal:
        total = sum((line.subtotal for line in self.items), start=Decimal("0.00"))
        return _q(total)

    def final_price(self) -> Decimal:
        subtotal = self.subtotal
        remaining = subtotal

        # Apply discounts sequentially; each discount can only reduce what's left.
        for discount in self._applied_discounts:
            amount = discount.apply(remaining)
            # Defensive clamp: never let remaining drop below zero.
            remaining = max(Decimal("0.00"), _q(remaining - amount))

        # Belt-and-braces: final price is never negative.
        return max(Decimal("0.00"), _q(remaining))


# ---------------------------------------------------------------------------
# Demo / tests
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    cart = ShoppingCart()

    cart.add_item(Product("A1", "Coffee beans", Decimal("12.50")), quantity=2)
    cart.add_item(Product("B7", "Mug", Decimal("8.00")), quantity=1)

    print(f"Subtotal:      {cart.subtotal}")

    cart.apply_discount(PercentageDiscount("SAVE10", Decimal("10")))
    cart.apply_discount(FixedAmountDiscount("OFF5", Decimal("5.00")))

    print(f"Final price:   {cart.final_price()}")

    # Re-applying the same code raises.
    try:
        cart.apply_discount(PercentageDiscount("save10", Decimal("10")))
    except DiscountAlreadyApplied as exc:
        print(f"Blocked:       {exc}")

    # Over-discounting: fixed amount larger than subtotal clamps to zero.
    big_cart = ShoppingCart()
    big_cart.add_item(Product("X", "Cheap item", Decimal("3.00")), quantity=1)
    big_cart.apply_discount(FixedAmountDiscount("HUGE", Decimal("100.00")))
    print(f"Clamped price: {big_cart.final_price()}")  # 0.00, never negative
```

## Design notes

**Money safety**
- All prices are `Decimal`. The `_q()` helper quantizes to cents with `ROUND_HALF_UP`, which is the conventional retail rounding mode.
- Every intermediate result goes through `_q()`, so no hidden sub-cent precision leaks into the final total.

**Non-negative final price**
- `FixedAmountDiscount.apply()` clamps the discount to the current remaining amount.
- `ShoppingCart.final_price()` additionally clamps the running total with `max(Decimal("0.00"), ...)` after each step — so even a badly-behaved future discount subclass can't produce a negative result.

**Idempotent discount codes**
- Codes are normalized (`strip().upper()`) before storage so `"SAVE10"` and `"save10 "` are treated as the same code.
- `_applied_codes` is a `set`, so calling `apply_discount` with an already-used code raises `DiscountAlreadyApplied`. This is the explicit "same code cannot be applied more than once to the same cart" guarantee.

**Extensibility**
- `Discount` is a strategy base class. Additional rules (BOGO, category discounts, minimum-spend thresholds) just implement `apply(subtotal)`.

## Example output

```
Subtotal:      33.00
Final price:   24.70
Blocked:       Discount code 'SAVE10' has already been applied to this cart
Clamped price: 0.00
```

